from pathlib import Path
import ast,gzip,hashlib,json,re,types,inspect,difflib
ROOT=Path('/home/osso/.worktrees/wow-ui-sim-p320-source')
E=ROOT/'data/patch-api/evidence/3.2.0-session-2026-10-09'
S=ROOT/'data/patch-api/sources'
def read(path): return json.loads(path.read_text())
def module(path):
    m=types.ModuleType(path.stem);m.__file__=str(path);exec(compile(path.read_text(),str(path),'exec'),m.__dict__);return m
def sha(data): return hashlib.sha256(data).hexdigest()
gen=module(ROOT/'tools/gen_patch_wikitext_register.py'); ext=module(ROOT/'tools/extract_patch_non_inventory.py')
base=module(Path('/tmp/p320-base-extract_patch_non_inventory.py'))
archive=json.loads(gzip.decompress((E/'historical-blobs.json.gz').read_bytes()))
manifest=read(E/'historical-inputs.json'); literal=read(E/'literal-inventory.json')
assert len(manifest['external'])==22 and len(archive)==81
for path,seal in manifest['external'].items():
    raw=(E/path).read_bytes(); assert sha(raw)==seal['sha256'] and len(raw)==seal['bytes'],path
for path,text in archive.items():
    raw=text.encode();seal=manifest['archived'][path];assert sha(raw)==seal['sha256'] and len(raw)==seal['bytes'],path
assert len(literal['api_event_array_occurrences'])==43 and len(literal['call_signatures'])==24 and len(literal['slash_command_occurrences'])==4
coverage=read(E/'historical-page-coverage.json'); rows=coverage['source_rows'];assert len(rows)==len({r['source_id'] for r in rows})==145
assert {s:sum(r['status']==s for r in rows) for s in ['bounded-coverage','audit-pending','metadata-only']}=={'bounded-coverage':30,'audit-pending':88,'metadata-only':27}
green=read(E/'own-sweep-green-results.json');neg=read(E/'negative-results.json'); assert sum(not r['ok'] for r in green.values())==13 and sum(not r['ok'] for r in neg.values())==14
own=read(S/'3.2.0-wikitext-register.json')['entries']; ownsymbols={r['symbol'] for r in own}; owntuples={(r['section'],r['symbol']) for r in own}
overlaps={}
for v in ['3.3.0','3.3.3','3.3.5','4.0.1']:
    later=read(S/(v+'-wikitext-register.json'));assert later.get('client_line','retail')=='retail'
    bare=ownsymbols & {r['symbol'] for r in later['entries']}; tuples=owntuples & {(r['section'],r['symbol']) for r in later['entries']}
    overlaps[v]={'bare_symbols':sorted(bare),'tuples':sorted(tuples),'matching_rows':[r for r in later['entries'] if r['symbol'] in bare]}
    if v!='4.0.1':assert not bare and not tuples
assert overlaps['4.0.1']['bare_symbols']==['END_REFUND']
refund=next(r for r in own if r['symbol']=='END_REFUND');expectation=green[refund['id']]['expected'];assert expectation['publication']=='absent' and expectation['superseded_by']=='wt-events-END_REFUND-87'
original_successor=json.loads(archive['data/patch-api/sources/4.1.0-wikitext-register.json']);assert any(r['id']=='wt-events-END_REFUND-87' and r['direction']=='removed' for r in original_successor['entries'])
ast_gen=ast.parse((ROOT/'tools/gen_patch_wikitext_register.py').read_text()); wiring={}
for name in ['parse_wrath_retail_summary','parse_wrath_retail_change_bullets']:
    funcs=[n for n in ast_gen.body if isinstance(n,ast.FunctionDef) and n.name==name];assert len(funcs)==1
    f=funcs[0];assert isinstance(f.body[-1],ast.Return)
    calls=[n.lineno for n in ast.walk(ast_gen) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id==name];assert calls
    wiring[name]={'definition_line':f.lineno,'own_return_line':f.body[-1].lineno,'call_lines':calls}
args=inspect.signature(ext.extract_text).parameters
for name in ['cataclysm_labeled_inventory','wrath_summary_markup','numbered_reflist']:assert args[name].default is False
reproductions=read(Path('/tmp/p320-independent-receipt.json'))['reproduction']; corrections=read(Path('/tmp/p320-independent-receipt.json'))['recorded_flags_corrections']['results']; ef={r['patch']:r['flags'] for r in corrections if r['kind']=='extract'}
extract_controls=[]
for row in reproductions:
    v=row['patch'];raw=(S/(v+'-api-changes.wikitext')).read_text();flags=ef.get(v,row['extractor_flags'])
    for mode,kwargs in [('default',{}),('recorded',{flag[2:].replace('-','_'):True for flag in flags})]:
        results=[]
        for label,m in [('merged',ext),('base',base)]:
            try:
                text=m.extract_text(raw,**kwargs);(Path('/tmp')/('p320-'+label+'-'+mode+'-'+v+'.txt')).write_text(text)
                results.append({'ok':True,'sha256':sha(text.encode()),'bytes':len(text.encode()),'matches_committed':text==(S/(v+'-api-changes.txt')).read_text()})
            except ValueError as error:results.append({'ok':False,'error':str(error)})
        if not (v=='3.2.0' and mode=='recorded'):
            assert results[0]==results[1],(v,mode,results)
        extract_controls.append({'patch':v,'mode':mode,'results':results})
failures=[r for r in extract_controls if r['mode']=='recorded' and (not r['results'][0]['ok'] or not r['results'][0]['matches_committed'])]
assert [r['patch'] for r in failures]==['12.0.5','12.0.7','12.1.0']
proof=read(E/'validator-development-proof.json')
assert proof['passed']==3 and proof['exit']==0
for filename,key in [('accounting-green.log','artifact_seal'),('historical-inputs.json','historical_manifest_seal'),('validate.py','validator_seal'),('validator-development-fixture.py','test_source_seal')]:
    b=(E/filename).read_bytes();assert sha(b)==proof[key]['sha256'] and len(b)==proof[key]['bytes'],filename
summary={'sealed_external':22,'archived_snapshots':81,'inventory':43,'signatures':24,'extract_rows':74,'slash_commands':4,'ledger_ids':145,'ledger_statuses':{'bounded-coverage':30,'audit-pending':88,'metadata-only':27},'original_gaps':13,'negative_gaps':14,'own_historical_publication_receipt':'1/1 (historical only)','original_accounting_receipt':'3/3 (historical only)','overlaps':overlaps,'original_END_REFUND_expectation':expectation,'wiring':wiring,'extract_signature':str(inspect.signature(ext.extract_text)),'extract_controls':extract_controls,'exact_inherited_extract_failures':failures,'model_closures':[],'limits':['No native client proof, current publication measurement or final handoff. Source/tools and original frozen historical receipt applicability only.']}
Path('/tmp/p320-artifact-results.json').write_text(json.dumps(summary,indent=2)+'\n')
print(json.dumps({k:v for k,v in summary.items() if k not in ['extract_controls']},indent=2))

